import argparse
import fcntl
import json
import os
from pathlib import Path
import pwd
import re
import shutil
import signal
import subprocess
import sys
import time
from evidence import atomic,business,digest,expected


class Interrupted(Exception):
    def __init__(self,code):self.code=code


def handler(signum,frame):raise Interrupted(130 if signum==signal.SIGINT else 143)


def terminate(process):
    if process is None:return
    try:os.killpg(process.pid,signal.SIGTERM)
    except ProcessLookupError:pass
    try:process.wait(timeout=.3)
    except subprocess.TimeoutExpired:
        try:os.killpg(process.pid,signal.SIGKILL)
        except ProcessLookupError:pass
        process.wait(timeout=1)


def main():
    parser=argparse.ArgumentParser()
    for name in ('root','run-id','worker','app','home'):parser.add_argument('--'+name,required=True)
    parser.add_argument('--timeout-ms',type=int,default=2000);args=parser.parse_args()
    if not re.fullmatch('[a-z][a-z0-9_-]{0,31}',args.run_id) or not 100<=args.timeout_ms<=3000:
        print('invalid run metadata',file=sys.stderr);return 2
    mask=os.umask(0o077);process=None;lock=None;run=None;status=73;reason='filesystem';worker_status=None;cancel_signal=None
    try:
        root=Path(args.root).resolve();app=Path(args.app).resolve();home=Path(args.home).resolve();worker=Path(args.worker).resolve()
        input_path=app/'data/input.json';expected(input_path)
        if not worker.is_file() or not home.is_dir():raise ValueError('missing execution dependency')
        root.mkdir(parents=True,exist_ok=True);root.chmod(0o700)
        lock=os.open(root/'.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:
            print('another scheduled attempt is running',file=sys.stderr);return 75
        runs=root/'runs';runs.mkdir(exist_ok=True);runs.chmod(0o700)
        run=runs/args.run_id
        if os.path.lexists(run):raise ValueError('run id already exists')
        run.mkdir(mode=0o700);run.chmod(0o700)
        stage=run/'work';stage.mkdir(mode=0o700);stage.chmod(0o700)
        environment={'HOME':str(home),'PATH':'/usr/bin:/bin','SHELL':'/bin/sh','LOGNAME':pwd.getpwuid(os.geteuid()).pw_name,
                     'LC_ALL':'C.UTF-8','PYTHONDONTWRITEBYTECODE':'1','PYTHON':sys.executable,'WORKER':str(worker),
                     'APP_ROOT':str(app),'RUN_STAGE':str(stage),'RUN_ID':args.run_id}
        trigger={'schema':1,'run_id':args.run_id,'uid':os.geteuid(),'cwd':str(home),'environment':environment,
                 'input_sha256':digest(input_path),'worker_sha256':digest(worker),'job_sha256':digest(Path(__file__).with_name('job.sh'))}
        atomic(run/'trigger.json',trigger)
        signal.signal(signal.SIGTERM,handler);signal.signal(signal.SIGINT,handler)
        started={'phase':'started','run_id':args.run_id,'monotonic_ns':time.monotonic_ns()}
        with (run/'events.jsonl').open('x') as stream:stream.write(json.dumps(started)+'\n');stream.flush();os.fsync(stream.fileno())
        try:
            with (run/'stdout.log').open('xb') as stdout,(run/'stderr.log').open('xb') as stderr:
                process=subprocess.Popen(['/bin/sh',str(Path(__file__).with_name('job.sh'))],cwd=home,env=environment,
                                         stdin=subprocess.DEVNULL,stdout=stdout,stderr=stderr,start_new_session=True)
                atomic(run/'process.json',{'pid':process.pid,'pgid':process.pid,'uid':os.geteuid()})
                process.wait(timeout=args.timeout_ms/1000)
            worker_status=process.returncode if process.returncode>=0 else 128-process.returncode
            if worker_status:
                status=worker_status;reason='worker_failure'
            else:
                try:
                    if digest(input_path)!=trigger['input_sha256']:raise ValueError('input changed during attempt')
                    business(input_path,stage/'result.json')
                except (OSError,ValueError,KeyError,TypeError,RecursionError):status=65;reason='invalid_result'
                else:
                    # A valid result is about to commit. Finish the bounded
                    # evidence publication instead of reclassifying committed
                    # business output as an interrupted failure.
                    signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
                    status=0;reason='success';os.replace(stage/'result.json',run/'result.json')
        except Interrupted as error:
            signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
            terminate(process);status=error.code;reason='interrupted'
            worker_status=process.returncode if process is not None and process.returncode>=0 else 128-process.returncode if process is not None else None
            cancel_signal=int(signal.SIGINT if error.code==130 else signal.SIGTERM)
            if process is not None:atomic(run/'process.json',{'pid':process.pid,'pgid':process.pid,'uid':os.geteuid()})
        except subprocess.TimeoutExpired:
            signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
            terminate(process);status=124;reason='timeout';worker_status=process.returncode if process.returncode>=0 else 128-process.returncode
            atomic(run/'process.json',{'pid':process.pid,'pgid':process.pid,'uid':os.geteuid()})
        signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
        ended={'phase':'ended','run_id':args.run_id,'monotonic_ns':time.monotonic_ns(),'exit_status':status,'worker_exit_status':worker_status,'cancel_signal':cancel_signal}
        with (run/'events.jsonl').open('a') as stream:stream.write(json.dumps(ended)+'\n');stream.flush();os.fsync(stream.fileno())
        report={'schema':1,'run_id':args.run_id,'completed':True,'success':status==0,'reason':reason,'exit_status':status,
                'worker_exit_status':worker_status,'input_sha256':digest(input_path),'stdout_sha256':digest(run/'stdout.log'),
                'stderr_sha256':digest(run/'stderr.log'),'result_sha256':digest(run/'result.json') if status==0 else None,'cancel_signal':cancel_signal}
        atomic(run/'report.json',report)
        try:print(json.dumps({'run_id':args.run_id,'success':status==0,'exit_status':status}),flush=True)
        except OSError:
            descriptor=os.open(os.devnull,os.O_WRONLY)
            try:os.dup2(descriptor,sys.stdout.fileno())
            finally:os.close(descriptor)
            print('run report committed; status output failed',file=sys.stderr);return 74
        return status
    except (OSError,ValueError):
        terminate(process);print('scheduled attempt setup/report failed',file=sys.stderr);return 73
    finally:
        if lock is not None:os.close(lock)
        os.umask(mask)


if __name__=='__main__':raise SystemExit(main())

