import hashlib
import json
import os
from pathlib import Path
import re
import tempfile


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def atomic(path,value):
    path=Path(path); descriptor,temporary=tempfile.mkstemp(prefix='.metadata-',dir=path.parent)
    try:
        with os.fdopen(descriptor,'w',encoding='utf8') as stream:
            json.dump(value,stream,sort_keys=True,separators=(',',':'));stream.flush();os.fsync(stream.fileno())
        os.replace(temporary,path)
    finally:
        if os.path.lexists(temporary):os.unlink(temporary)


def expected(input_path):
    rows=json.loads(Path(input_path).read_text(encoding='utf8'))
    if not isinstance(rows,list) or len(rows)>10000:raise ValueError('input rows')
    seen=set();total=0
    for row in rows:
        if not isinstance(row,dict) or set(row)!={'id','amount'} or not isinstance(row['id'],str) or not row['id'] or row['id'] in seen:
            raise ValueError('input identity')
        if type(row['amount']) is not int or not -1000000<=row['amount']<=1000000:raise ValueError('input amount')
        seen.add(row['id']);total+=row['amount']
    return {'count':len(rows),'total':total,'ids':sorted(seen)}


def business(input_path,result_path):
    value=json.loads(Path(result_path).read_text(encoding='utf8'))
    if value!=expected(input_path) or type(value.get('count')) is not int or type(value.get('total')) is not int:
        raise ValueError('business result mismatch')
    return value


def inspect(run,input_path):
    run=Path(run);trigger=json.loads((run/'trigger.json').read_text());report=json.loads((run/'report.json').read_text())
    events=[json.loads(line) for line in (run/'events.jsonl').read_text().splitlines()]
    if not isinstance(trigger,dict) or set(trigger)!={'schema','run_id','uid','cwd','environment','input_sha256','worker_sha256','job_sha256'}:raise ValueError('trigger fields')
    if not isinstance(report,dict) or set(report)!={'schema','run_id','completed','success','reason','exit_status','worker_exit_status','input_sha256','stdout_sha256','stderr_sha256','result_sha256','cancel_signal'}:raise ValueError('report fields')
    if type(trigger['schema']) is not int or trigger['schema']!=1:raise ValueError('trigger schema')
    if type(report['schema']) is not int or report['schema']!=1:raise ValueError('report schema')
    for value in [trigger[key] for key in ('input_sha256','worker_sha256','job_sha256')]+[report[key] for key in ('input_sha256','stdout_sha256','stderr_sha256')]:
        if not isinstance(value,str) or not re.fullmatch('[0-9a-f]{64}',value):raise ValueError('digest format')
    environment=trigger['environment']
    if not isinstance(environment,dict) or set(environment)!={'HOME','PATH','SHELL','LOGNAME','LC_ALL','PYTHONDONTWRITEBYTECODE','PYTHON','WORKER','APP_ROOT','RUN_STAGE','RUN_ID'} or any(not isinstance(value,str) for value in environment.values()):raise ValueError('execution environment schema')
    if environment['PATH']!='/usr/bin:/bin' or environment['SHELL']!='/bin/sh' or environment['RUN_ID']!=run.name or trigger['cwd']!=environment['HOME']:raise ValueError('execution environment binding')
    if type(trigger['uid']) is not int or trigger['uid']<0 or trigger['uid']!=run.stat().st_uid:raise ValueError('execution owner')
    if trigger['run_id']!=run.name or report['run_id']!=run.name or trigger['input_sha256']!=digest(input_path):raise ValueError('run binding')
    if report['completed'] is not True or type(report['success']) is not bool:raise ValueError('completion record')
    if len(events)!=2 or [row['phase'] for row in events]!=['started','ended']:raise ValueError('event completion')
    if set(events[0])!={'phase','run_id','monotonic_ns'} or set(events[1])!={'phase','run_id','monotonic_ns','exit_status','worker_exit_status','cancel_signal'}:raise ValueError('event fields')
    if any(row['run_id']!=run.name for row in events):raise ValueError('event identity')
    if type(events[0]['monotonic_ns']) is not int or type(events[1]['monotonic_ns']) is not int or events[0]['monotonic_ns']<0 or events[1]['monotonic_ns']<events[0]['monotonic_ns']:
        raise ValueError('event order')
    if events[1]['exit_status']!=report['exit_status'] or events[1]['worker_exit_status']!=report['worker_exit_status']:raise ValueError('exit status binding')
    if events[1]['cancel_signal']!=report['cancel_signal']:raise ValueError('cancellation binding')
    if report['reason']=='interrupted':
        if type(report['cancel_signal']) is not int or report['cancel_signal'] not in (2,15) or report['exit_status']!=128+report['cancel_signal']:raise ValueError('cancellation signal')
    elif report['cancel_signal'] is not None:raise ValueError('unexpected cancellation')
    if report['stdout_sha256']!=digest(run/'stdout.log') or report['stderr_sha256']!=digest(run/'stderr.log'):raise ValueError('raw log binding')
    if report['input_sha256']!=digest(input_path):raise ValueError('input changed')
    if type(report['exit_status']) is not int or not 0<=report['exit_status']<=255:raise ValueError('exit range')
    if type(report['worker_exit_status']) is not int or not 0<=report['worker_exit_status']<=255:raise ValueError('worker exit range')
    process=json.loads((run/'process.json').read_text())
    if not isinstance(process,dict) or set(process)!={'pid','pgid','uid'} or any(type(value) is not int for value in process.values()):raise ValueError('process fields')
    if process['pid']<=0 or process['pgid']!=process['pid'] or process['uid']!=trigger['uid']:
        raise ValueError('native process identity')
    if report['success']:
        if report['reason']!='success' or report['exit_status']!=0 or report['worker_exit_status']!=0:raise ValueError('success exit')
        business(input_path,run/'result.json')
        if report['result_sha256']!=digest(run/'result.json'):raise ValueError('result binding')
    else:
        if report['exit_status']==0 or report['reason']=='success' or report['result_sha256'] is not None or (run/'result.json').exists():raise ValueError('false success')
        reason=report['reason'];status=report['exit_status'];worker=report['worker_exit_status']
        if reason=='worker_failure':valid=worker!=0 and worker==status
        elif reason=='invalid_result':valid=status==65 and worker==0
        elif reason=='timeout':valid=status==124 and worker>=128
        elif reason=='interrupted':valid=status in (130,143)
        else:valid=False
        if not valid:raise ValueError('failure classification')
    return {'verified':True,'run_id':run.name,'success':report['success'],'exit_status':report['exit_status']}

